# A call Julia resolved names a method, never one of dart:_wasm's intrinsics; a call of a builtin is
# Julia's own operation: `===` dart's identical, `ifelse` a select, a conversion or a shift its case of
# dart's switch, and any other intrinsic the operator dart intrinsifies on an int, double or bool receiver (dart's
# generateInstanceIntrinsic, :985): a binary one through the binary operator map, a unary one through
# the unary map. An 8- or 16-bit integer, an i32 in its type's form, is read in its operation's
# view and its result put back in that form; Bool's bitwise operations and equality need neither. No arm is null, as dart's.
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, node::Union{NirCall,NirInvoke})::Union{WasmBuilder.IR.ValueType,Nothing}
    if node isa NirInvoke
        local target = nir_invoke_target(node)
        local string_op = generate_static_intrinsic(Val(:string_data_op), target)
        string_op === nothing || return generate_static_intrinsic(self, Val(:string_data), string_op, node.args[2:end])
        local intrinsic = StaticIntrinsic_from_procedure(target)
        intrinsic === nothing && return nothing
        reject!(Unported("dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic"), "the static intrinsic $intrinsic")
    end
    local f = nir_callee(node)
    local args = node.args[2:end]
    # each family of arms is its own method, compiled only when a program reaches it
    f === Core.:(===) && length(args) == 2 && return generate_static_intrinsic(self, Val(:identical), f, args)
    f === Core._svec_len && length(args) == 1 && return generate_static_intrinsic(self, Val(:svec_len), f, args)
    f === Core._svec_ref && length(args) == 2 && return generate_static_intrinsic(self, Val(:svec_ref), f, args)
    f === Core.ifelse && length(args) == 3 && return generate_static_intrinsic(self, Val(:ifelse), f, args)
    f isa Core.IntrinsicFunction || return nothing
    local type_operand = length(args) == 2 ? dart_type_of(self, args[1]) : nothing
    type_operand isa DataType && type_operand <: Type && length(type_operand.parameters) == 1 && type_operand.parameters[1] isa Type &&
        return generate_static_intrinsic(self, Val(:conversion), f, args)
    f === Core.Intrinsics.flipsign_int && length(args) == 2 && return generate_static_intrinsic(self, Val(:flipsign), f, args)
    length(args) == 2 && (f === Core.Intrinsics.shl_int || f === Core.Intrinsics.lshr_int || f === Core.Intrinsics.ashr_int) &&
        return generate_static_intrinsic(self, Val(:shift), f, args)
    length(args) == 2 && (f === Core.Intrinsics.checked_sdiv_int || f === Core.Intrinsics.checked_srem_int ||
                          f === Core.Intrinsics.checked_udiv_int || f === Core.Intrinsics.checked_urem_int) &&
        return generate_static_intrinsic(self, Val(:checked_division), f, args)
    local narrow(t::Type) = generate_static_intrinsic(Val(:narrow), t)
    all(a -> narrow(dart_type_of(self, a)), args) && allequal(dart_type_of(self, a) for a in args) && 1 <= length(args) <= 2 &&
        return generate_static_intrinsic(self, Val(:narrow_operator), f, args)
    return generate_static_intrinsic(self, Val(:operator), f, args)
end

# Julia's integer forms, which the arms share: a type held in its wasm number type at its own width
# (Int32 and UInt32 in an i32, Int64 and UInt64 in an i64, Float32 in an f32, Float64 in an f64)
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:full}, t::Type, w::WasmBuilder.IR.ValueType)::Bool =
    t isa DataType && isprimitivetype(t) && w isa WasmBuilder.IR.NumType && 8 * sizeof(t) == 8 * WasmBuilder.byte_size(w)

# An 8- or 16-bit integer is an i32 held as Julia's ABI holds it (Translator.translateType):
# sign-extended for a signed type, zero-extended for an unsigned one. An operation reads the
# operand in the view it needs (a signed comparison, division or arithmetic shift the
# sign-extended bits, an unsigned one the zero-extended bits) and puts a result back in its type's
# form, as Julia's codegen computes at the type's own width (an i8 or i16 in LLVM).
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:narrow}, t::Type)::Bool = t isa DataType && t <: Base.BitInteger && sizeof(t) < 4

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:put_form}, b::WasmBuilder.InstructionsBuilder, t::Type)::Nothing = (sizeof(t) == 1 ?
    (t <: Signed ? WasmBuilder.i32_extend8_s(b) : (WasmBuilder.i32_const(b, 255); WasmBuilder.i32_and(b))) :
    (t <: Signed ? WasmBuilder.i32_extend16_s(b) : (WasmBuilder.i32_const(b, 65535); WasmBuilder.i32_and(b))); nothing)

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:signed_view}, b::WasmBuilder.InstructionsBuilder, t::Type)::Nothing =
    (t <: Unsigned && (sizeof(t) == 1 ? WasmBuilder.i32_extend8_s(b) : WasmBuilder.i32_extend16_s(b)); nothing)

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:unsigned_view}, b::WasmBuilder.InstructionsBuilder, t::Type)::Nothing =
    (t <: Signed && (WasmBuilder.i32_const(b, sizeof(t) == 1 ? 255 : 65535); WasmBuilder.i32_and(b)); nothing)

# a String's data operations (src/julia/wasm_array.jl), the calls dart's String patches make on a
# String's `_data`: each reads the field (an InstanceGet of the String class's `_data`, its
# ClassField) and applies the WasmArray operation, one instruction as dart's intrinsifier emits it:
# WasmArrayRef.length (intrinsics.dart:626, array.len), I8ArrayExt.readUnsigned (:1351, array.get_u),
# the WasmArray constructor (:1959, array.new_default, here inside the String's struct, its header
# first) and WasmArrayExt.copy (:1254, array.copy). An Int offset or length is wrapped to the i32 a
# wasm array takes, as dart wraps its int.
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:string_data_op}, target::Core.MethodInstance)::Union{Symbol,Nothing} =
    target.def in methods(wasm_string_length) ? :length : target.def in methods(wasm_string_codeunit) ? :codeunit :
    target.def in methods(wasm_string_alloc) ? :alloc : target.def in methods(wasm_string_copy!) ? :copy : nothing

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:string_data}, op::Symbol, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local i32, i64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64
    local at = "$(code_gen.enclosing_member): a String's data"
    local info = get(t.class_info, String, nothing)
    info === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: a String's data operation where String has no class info"), at)
    local data_index = t.field_index[only(class_instance_fields(String, at))]
    local array_type = array_type_for_dart_type(t, WasmI8; mutable_ = true)
    local data_of(s::NirValue) = (translate_expression(code_gen, s, info.non_nullable_type); WasmBuilder.struct_get(b, info.struct_, data_index))
    local offset(v::NirValue) = (translate_expression(code_gen, v, i64); WasmBuilder.i32_wrap_i64(b))
    if op === :length
        data_of(args[1])
        WasmBuilder.array_len(b)
        WasmBuilder.i64_extend_i32_u(b)
        return i64
    elseif op === :codeunit
        data_of(args[1])
        offset(args[2])
        WasmBuilder.array_get_u(b, array_type)
        return i32
    elseif op === :alloc
        push_object_header_fields(b, t, info)
        offset(args[1])
        WasmBuilder.array_new_default(b, array_type)
        WasmBuilder.struct_new(b, info.struct_)
        return info.non_nullable_type
    elseif op === :copy
        data_of(args[1])
        offset(args[2])
        data_of(args[3])
        offset(args[4])
        offset(args[5])
